var n=`0608-msemen`;var s=`world-0608`;var o=`MA`;var i=`northern-africa`;var a=8;var r=71;var l={en:`Msemen`,ua:`Мсемен`};var u={en:`Msemen is a Morocco classic prepared with all-purpose flour, semolina flour. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Мсемен, страва кухні країни Марокко зі складниками: пшеничне борошно універсальне, семоліна. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 20 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 20 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:20,i:[[`all-purpose-flour`,420,`g`],[`semolina-flour`,90,`g`],[`water`,305,`ml`],[`table-salt`,7,`g`]]},{en:`Butter and oil small portions of dough, fold repeatedly into squares to create delicate layers rather than stacking loose pastry sheets.`,ua:`Змащуйте невеликі порції тіста маслом та олією й кілька разів складайте квадратами, щоб утворити шари без окремих листів філо.`,t:[`layered-assembly`],m:12,i:[[`unsalted-butter`,100,`g`],[`sunflower-oil`,65,`ml`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 25 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 25 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:25,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`honey`,85,`g`]]}];var h={slug:n,id:s,country:`MA`,region:i,servings:8,minutes:71,title:l,text:u,steps:d};export{o as country,h as default,s as id,r as minutes,i as region,a as servings,n as slug,d as steps,u as text,l as title};